            key: "secret",
        },
    },
    peerAddress: {
        ip: "1.1.1.1",
    },
    protocol: {
        ikev1: {
            ikeCryptoProfile: example.name,
        },
    },
}, {
    dependsOn: [example],
});
// --- DEPENDENCY 3: IPsec Tunnel ---
// This defines the tunnel interface itself and uses the IKE Gateway.
